    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """

    def check_prime(num):
        """Check if a given number is prime."""
        if num <= 1:
            return False
        elif num == 2:
            return True
        elif num % 2 == 0:
            return False
        else:
            for i in range(3, int(num**0.5) + 1, 2):
                if num % i == 0:
                    return False
            return True

    if check_prime(n):
        return x
    else:
        return y

